def parse_pairs(s):
    pairs = {}
    key = None
    value = ""
    in_quote = False
    buffer = []

    for char in s:
        if char == ";":
            if key is not None and value:
                pairs[key.strip()] = value if not in_quote else value.strip("'")
            key = None
            value = ""
            in_quote = False
            buffer = []
        elif char == "=":
            if key is None:
                key = "".join(buffer)
                buffer = []
            else:
                key += char
        elif char == "'":
            in_quote = not in_quote
        elif key is not None:
            value += char
        else:
            buffer.append(char)

    if key is not None and value:
        pairs[key.strip()] = value if not in_quote else value.strip("'")

    return pairs
