class Limiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.record = {}

    def hit(self, key, now):
        if key not in self.record:
            self.record[key] = [0, now - self.window]
        hits, start = self.record[key]
        if now - start > self.window:
            hits = 0
            start = now - self.window
        hits += 1
        if hits <= self.limit:
            self.record[key] = [hits, start]
            return True
        return False

    def count(self, key, now):
        if key in self.record:
            hits, _ = self.record[key]
            if now - self.record[key][1] > self.window:
                return 0
            return hits
        return 0
